--
-- Table structure for table `message_record_fallback`
--

DROP TABLE IF EXISTS `message_record_fallback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `message_record_fallback` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `message_json` text NOT NULL COMMENT '消息JSON',
  `retry_count` int DEFAULT '0',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间',
  `status` tinyint DEFAULT '0' COMMENT '0-待重试,1-成功,2-失败',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
