-- Table structure for table `refund_notify_message`
--

DROP TABLE IF EXISTS `refund_notify_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `refund_notify_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `notify_id` varchar(64) NOT NULL COMMENT '通知唯一ID(UUID)',
  `refund_id` varchar(64) NOT NULL COMMENT '退款单ID',
  `target_user_id` varchar(64) NOT NULL COMMENT '目标用户ID(商家ID或用户ID)',
  `target_user_type` varchar(20) NOT NULL COMMENT '目标用户类型: MERCHANT/USER',
  `title` varchar(200) NOT NULL COMMENT '通知标题',
  `content` text NOT NULL COMMENT '通知内容',
  `action` varchar(20) NOT NULL COMMENT '动作: APPLY/AGREE/REJECT',
  `is_read` tinyint DEFAULT '0' COMMENT '是否已读: 0-未读,1-已读',
  `read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `push_status` tinyint DEFAULT '0' COMMENT '推送状态: 0-待推送,1-推送成功,2-推送失败',
  `retry_count` int DEFAULT '0' COMMENT '重试次数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_id_read` (`target_user_id`,`is_read`),
  KEY `idx_refund_id` (`refund_id`),
  KEY `idx_push_status` (`push_status`)
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='退款通知记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

